#!/bin/bash
# Community Island (theme id `community`, Campfire Commons): GPT prop sheets through the Codex CLI, 2x2 pieces on white.
# usage: scripts/themes/community-gen.sh <id> "<four pieces description>"
# writes concepts/themes/community-gen/<id>.png; scripts/themes/community-trace.py cuts and vectorises it.
D="/Users/pragadees.xd/Downloads/Ducky Land/concepts/themes/community-gen"
CODEX=$(find /Applications/ChatGPT.app/Contents/Resources -maxdepth 4 -name codex -type f -perm -u+x 2>/dev/null | head -1)
id="$1"; desc="$2"
P="concept.png is the approved concept for the COMMUNITY island in our game Ducky Land (a cosy hangout island for a chat community, mellowed purples), centre.png is its campfire plaza. home-props.png and home-island.png show our game's exact ART STYLE: flat vector cartoon, clean dark olive-ink outlines (#39472D, even weight, about 3px), flat fills with ONE soft cream highlight upper-left and ONE soft darker shade band lower-right per shape, no gradients, no texture, no noise, no glow effects. Draw game PROPS as a sprite sheet: a 2x2 grid of FOUR separate pieces, each one centred in its own quarter, NOTHING touching, wide pure white (#FFFFFF) margins around and between them, no ground, no grass, no shadows on the ground, no background, no text, no letters, no numbers, no logos, no Duckies. Camera: the same gentle 3/4 bird's-eye view as concept.png (we see the front face and a bit of the top). Palette: dusty blurple #6F78D8, soft blurple #8A91E0, lavender #C9C3F2, pale lilac #E6E1FA, slate #5B6178, soft blue #8EC5F0, mint green #6FCF97, online green #5BC48A, badge red #E8636A, boost pink #F28FD0, cream #FFF0C7, warm wood #C98A4B, dark wood #885931, leaf green #4AA539. Each piece must match the detail level of concept.png, crisp and readable when small. The four pieces: $desc Square image 1536x1536. Save it in the current working directory as $id.png."
"$CODEX" exec -C "$D" -s workspace-write --skip-git-repo-check -c model_reasoning_effort=high -i "$D/concept.png" -i "$D/centre.png" -i "$D/home-props.png" -i "$D/home-island.png" -- "Use the imagegen skill, built-in image_gen tool, with the attached images as references. Generate ONE image. $P Reply with only the absolute path." < /dev/null > "$D/log-$id.txt" 2>&1
[ -f "$D/$id.png" ] || { f=$(ls -t ~/.codex/generated_images/*/*.png 2>/dev/null | head -1); echo "missing $id (latest gen $f)" >> "$D/missing.txt"; }
